T = int(input())
for i in range(T):
	(n, k) = map(int, input().split())
	w = list(map(int, input().split()))
	t = list(map(int, input().split()))
	c = 0
	s = []
	for i in range(n):
		s.append(w[i] + t[i])
	s.sort()
	for i in range(n):
		if s[i] > k:
			break
		k -= s[i]
		c += 1
	if c != n:
		for j in range(n):
			if w[j] <= k:
				if k + t[j] >= s[i] or w[j] + t[j] >= s[i]:
					c += 1
					break
	print(c)
